WITH latest_match AS (SELECT s.id, s.customer_id, s.balance, s.opened_date, top1.merchant, top1.transaction_txn_type FROM accounts s JOIN LATERAL (SELECT c.merchant, c.txn_type AS transaction_txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE), enriched AS (SELECT a.id, a.customer_id, a.opened_date, a.merchant, p.country, p.email, p.name FROM latest_match a LEFT JOIN customers p ON a.customer_id = p.id), with_dims AS (SELECT e.*, p.age, p.credit_limit, p.city FROM enriched e INNER JOIN customers p ON e.customer_id = p.id WHERE p.signup_date < '2024-07-01'), enriched_accounts AS (SELECT id, customer_id, merchant, country, email, city, ROUND(age / SUM(age) OVER (PARTITION BY merchant, country), 4) AS age_share, AVG(credit_limit) OVER (PARTITION BY city ORDER BY age, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS credit_limit_avg_3, AVG(credit_limit) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS credit_limit_avg_5_prior, CUME_DIST() OVER (PARTITION BY YEAR(opened_date), country ORDER BY credit_limit) AS credit_limit_cume_dist, STDDEV_SAMP(age) OVER (PARTITION BY country) AS country_stddev_samp_age FROM with_dims), enriched_accounts_2 AS (SELECT *, SUM(credit_limit_cume_dist) OVER (PARTITION BY customer_id ORDER BY age_share, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_credit_limit_cume_dist, SUM(credit_limit_avg_5_prior) OVER (PARTITION BY customer_id, merchant) AS customer_id_sum_credit_limit_avg_5_prior, AVG(credit_limit_cume_dist) OVER (PARTITION BY customer_id ORDER BY credit_limit_avg_3, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS credit_limit_cume_dist_avg_6 FROM enriched_accounts), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY credit_limit_cume_dist_avg_6, id) AS dedup_rank FROM enriched_accounts_2 QUALIFY dedup_rank = 1) SELECT id, merchant, country, email, city, credit_limit_avg_3, credit_limit_cume_dist, running_credit_limit_cume_dist, customer_id_sum_credit_limit_avg_5_prior FROM latest ORDER BY city DESC NULLS LAST, credit_limit_cume_dist DESC;
